              <div class="sa-row"><span class="sa-label">\u6A21\u578B</span><select class="sa-select" id="sa-api-model" style="flex:1">${e.customApiModel?`<option value="${F(e.customApiModel)}" selected>${F(e.customApiModel)}</option>`:'<option value="">\u8BF7\u5148\u83B7\u53D6\u6A21\u578B\u5217\u8868</option>'}</select><button class="sa-btn sa-btn-sm" id="sa-fetch-models">\u83B7\u53D6\u5217\u8868</button></div>
